    except Exception:
        uf_prev = None
    if K_prev is None or not math.isfinite(K_prev):
        K_prev = G0
    K_prev = _clip(K_prev, K_MIN, K_MAX)
    if not math.isfinite(i_prev):
        i_prev = 0.0
    i_prev = _clip(i_prev, -INT_LIM, INT_LIM)
    if yf_prev is None or not math.isfinite(yf_prev):
